// Language picker in the header (markup is generated by scripts/build-i18n.mjs). The menu is a
// list of plain links, so it works without this script; this adds placement under the button,
// remembers the choice in this browser, and on an English page offers (never forces) the
// language the visitor chose before or their browser speaks.
(() => {
	const button = document.querySelector('button.lang');
	const menu = document.getElementById('lang-menu');
	if (!button || !menu) return;
	if (!('popover' in HTMLElement.prototype)) {
		button.hidden = true;
		return;
	}
	const store = {
		get: () => {
			try {
				return localStorage.getItem('lang');
			} catch {
				return null;
			}
		},
		set: (v) => {
			try {
				localStorage.setItem('lang', v);
			} catch {}
		},
	};
	const items = [...menu.querySelectorAll('[data-lang]')];

	menu.addEventListener('click', (e) => {
		const item = e.target.closest('[data-lang]');
		if (item) store.set(item.dataset.lang);
	});
	menu.addEventListener('beforetoggle', (e) => {
		if (e.newState !== 'open') return;
		placePopover(menu, button);
	});

	// A page that exists only in English (terms, privacy) keeps the chosen language going: its links
	// to other pages point at that language's copies. Nothing is redirected.
	if (menu.hasAttribute('data-english-only')) {
		const chosen = items.find((i) => i.dataset.lang !== 'en' && i.dataset.lang === store.get());
		if (chosen) {
			const home = chosen.getAttribute('href');
			for (const a of document.querySelectorAll('header.site a[href], footer.site a[href], main a[href]')) {
				const href = a.getAttribute('href');
				if (a.closest('#lang-menu') || /^([a-z][a-z0-9+.-]*:|\/\/|#|\?)/i.test(href) || /^(privacy|terms)\.html/.test(href)) continue;
				a.setAttribute('href', href === './' ? home : home + href.replace(/^\.\//, ''));
			}
		}
		return;
	}

	const current = items.find((i) => i.getAttribute('aria-checked') === 'true')?.dataset.lang;
	if (current !== 'en') return;
	const stored = store.get();
	if (stored === 'en') return;
	const speaks = (code) =>
		(navigator.languages || [navigator.language]).some((l) => {
			l = (l || '').toLowerCase();
			if (code === 'zh-hans') return l.startsWith('zh') && !/(tw|hk|mo|hant)/.test(l);
			return l === code || l.startsWith(`${code}-`);
		});
	const pick = items.find((i) => i.dataset.lang !== 'en' && i.dataset.suggest && (stored ? i.dataset.lang === stored : speaks(i.dataset.lang)));
	if (!pick) return;

	const bar = document.createElement('div');
	bar.className = 'lang-suggest';
	bar.lang = pick.lang;
	const a = Object.assign(document.createElement('a'), { href: pick.href, textContent: pick.dataset.suggest });
	a.addEventListener('click', () => store.set(pick.dataset.lang));
	const close = Object.assign(document.createElement('button'), { type: 'button', textContent: '×' });
	close.setAttribute('aria-label', 'Close');
	close.addEventListener('click', () => {
		store.set('en');
		bar.remove();
	});
	bar.append(a, close);
	document.body.append(bar);
})();
